    mut lmc: *const ZopfliLongestMatchCache,
    mut pos: size_t,
    mut length: size_t,
    mut sublen: *mut c_ushort,
) {
    if length < 3 as size_t {
        return;
    }

    let maxlength: c_uint = ZopfliMaxCachedSublen(lmc, pos, length);
    let lmc_view: &ZopfliLongestMatchCache = unsafe { &*lmc }; // SAFETY: caller provides a valid pointer to ZopfliLongestMatchCache as required by the original function.
    let cache = unsafe {
        lmc_view.sublen.add(
            (ZOPFLI_CACHE_LENGTH as size_t)
                .wrapping_mul(pos)
                .wrapping_mul(3 as size_t),
        )
    }; // SAFETY: pointer arithmetic matches the original offset computation and relies on the same allocation/layout guarantees.

    let mut prevlength: usize = 0;
    let mut j: usize = 0;
    let max_j: usize = ZOPFLI_CACHE_LENGTH as usize;

    while j < max_j {
        let base = j * 3;
        let length_0 = unsafe { *cache.add(base) as c_uint + 3 as c_uint }; // SAFETY: base is within the same cache row bounds under the same preconditions as the original code.
        let dist = unsafe {
            *cache.add(base + 1) as c_uint + ((*cache.add(base + 2) as c_uint) << 8)
        }; // SAFETY: base+1 and base+2 are within the same cache row bounds under the same preconditions as the original code.

        let mut i = prevlength;
        let end = length_0 as usize;
